extends Node

func refresh_rows() -> void:
	var rows = Directory.list_entries()
	for row in rows:
		var key = row.get_file_name()
		var visible = Filter.allows(key)
		Grid.apply_visibility(key, visible)
	Status.show_count(rows.size())
	Grid.request_layout()
	Grid.refresh_selection(Directory.lookup(Catalog.KEY_ACTIVE))
	Status.update_banner(Filter.describe_rule(Grid.current_mode))
	Status.report_location(Directory.render_label(Grid.current_path))

extends Node

func run_sample() -> void:
	var samples = Recorder.load_samples()
	for sample in samples:
		var channel = sample.get_channel()
		var average = Meter.measure(channel)
		Report.record_reading(channel, average)
	Clock.mark_frame(samples.size())
	Recorder.finish_capture()
	Report.update_average(Recorder.lookup(Channel.PRIMARY))
	Clock.mark_average(Meter.describe_readings(Report.current_average))
	Clock.update_deadline(Recorder.render_label(Report.until_timestamp))
